import { Project } from '../../../src'
import { path } from '@servicenow/sdk-build-core'
import { getMergedRecordUpdates, unzipInputArray, findInput } from './test-utils'

describe('Catalog Item Flow Tests', () => {
    describe('getCatalogVariables Action', () => {
        test('should create flow with getCatalogVariables action and catalog item reference', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toHaveLength(1)
            const flowRecord = merged['sys_hub_flow'][0]
            expect(flowRecord.name).toBe('Test flow for service catalog using fluent')
            expect(flowRecord.description).toBe('Test flow for service catalog using fluent desc')

            // Verify trigger instance
            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)
            const triggerInstance = merged['sys_hub_trigger_instance_v2'][0]
            expect(triggerInstance.trigger_type).toBe('service_catalog') // service catalog trigger

            // Verify action instances exist
            expect(merged['sys_hub_action_instance_v2']).toHaveLength(2) // getCatalogVariables + log
            const getCatalogVarsAction = merged['sys_hub_action_instance_v2'][0]
            expect(getCatalogVarsAction).toBeDefined()
            expect(getCatalogVarsAction.sys_id).toBeDefined()
        })

        test('should handle catalog variables as array of variable references', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            const getCatalogVarsAction = merged['sys_hub_action_instance_v2'][0]
            const inputs = unzipInputArray(getCatalogVarsAction.values)

            // Find catalog_variables input
            const catalogVarsInput = findInput(inputs, 'catalog_variables')
            expect(catalogVarsInput).toBeDefined()

            // Verify it's defined and has a value (catalog variables are serialized as UUIDs)
            expect(catalogVarsInput.value).toBeDefined()
            expect(typeof catalogVarsInput.value).toBe('string')

            // Verify parameter type is slushbucket
            expect(catalogVarsInput.parameter).toBeDefined()
            expect(catalogVarsInput.parameter.type).toBe('slushbucket')

            // Verify scriptActive is false
            expect(catalogVarsInput.scriptActive).toBe(false)

            // Verify value format: comma-separated list of UUID:table_name pairs
            expect(catalogVarsInput.value).toMatch(/^[a-f0-9]{32}:item_option_new(,[a-f0-9]{32}:item_option_new)*$/)

            // Verify displayValue matches value for catalog variables
            expect(catalogVarsInput.displayValue).toBe(catalogVarsInput.value)
        })

        test('should access dynamic catalog variable outputs with correct types', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            // Verify log action exists
            const logAction = merged['sys_hub_action_instance_v2'][1]
            expect(logAction).toBeDefined()
            expect(logAction.sys_id).toBeDefined()

            // Verify log action has inputs
            const inputs = unzipInputArray(logAction.values)
            expect(inputs.length).toBe(2) // log_level and log_message

            // Validate log_level input
            const logLevelInput = findInput(inputs, 'log_level')
            expect(logLevelInput).toBeDefined()
            expect(logLevelInput.value).toBe('info')
            expect(logLevelInput.displayValue).toBe('info')
            expect(logLevelInput.scriptActive).toBe(false)
            expect(logLevelInput.parameter.type).toBe('choice')

            // Validate log_message input
            const logMessageInput = findInput(inputs, 'log_message')
            expect(logMessageInput).toBeDefined()
            expect(logMessageInput.value).toBeDefined()
            expect(logMessageInput.scriptActive).toBe(false)
            expect(logMessageInput.parameter.type).toBe('string')

            // Verify log_message contains data pills referencing catalog variable outputs
            // Format: {{action-uuid.variableName}}
            expect(logMessageInput.value).toContain('{{')
            expect(logMessageInput.value).toContain('}}')
            expect(logMessageInput.value).toContain('.email')
            expect(logMessageInput.value).toContain('.html')
            expect(logMessageInput.value).toContain('.ipAddress')

            // Verify data pill format uses UUID with hyphens
            expect(logMessageInput.value).toMatch(
                /\{\{[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\.(email|html|ipAddress)\}\}/
            )

            // Verify displayValue matches value for data pills
            expect(logMessageInput.displayValue).toBe(logMessageInput.value)
        })
    })

    describe('createCatalogTask Action', () => {
        test('should create flow with createCatalogTask action', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-create-task.now.ts'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toHaveLength(1)
            const flowRecord = merged['sys_hub_flow'][0]
            expect(flowRecord.name).toBe('Create Catalog Task with Variables')
            expect(flowRecord.description).toBe(
                'Demonstrates creating a catalog task with variables from a template catalog item'
            )

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toHaveLength(2) // createCatalogTask + log

            // Verify createCatalogTask action exists
            const createTaskAction = merged['sys_hub_action_instance_v2'][0]
            expect(createTaskAction).toBeDefined()
            expect(createTaskAction.sys_id).toBeDefined()

            // Verify action has inputs
            const inputs = unzipInputArray(createTaskAction.values)
            expect(inputs.length).toBeGreaterThan(0)

            // Check template_catalog_item input exists
            const templateInput = findInput(inputs, 'template_catalog_item')
            expect(templateInput).toBeDefined()
            expect(templateInput.value).toBeDefined()
        })

        test('should pass catalog_variables array to createCatalogTask', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-create-task.now.ts'
            )

            const createTaskAction = merged['sys_hub_action_instance_v2'][0]
            const inputs = unzipInputArray(createTaskAction.values)

            // Find catalog_variables input
            const catalogVarsInput = findInput(inputs, 'catalog_variables')
            expect(catalogVarsInput).toBeDefined()

            // Verify it has a value (catalog variables are serialized as UUIDs)
            expect(catalogVarsInput.value).toBeDefined()
            expect(typeof catalogVarsInput.value).toBe('string')
        })

        test('should access outputs from createCatalogTask in log action', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-create-task.now.ts'
            )

            // Verify log action exists
            const logAction = merged['sys_hub_action_instance_v2'][1]
            expect(logAction).toBeDefined()

            // Verify log action has inputs
            const inputs = unzipInputArray(logAction.values)
            expect(inputs.length).toBe(2) // log_level and log_message

            // Validate log_level input
            const logLevelInput = findInput(inputs, 'log_level')
            expect(logLevelInput).toBeDefined()
            expect(logLevelInput.value).toBe('info')
            expect(logLevelInput.parameter.type).toBe('choice')
            expect(logLevelInput.scriptActive).toBe(false)

            // Validate log_message input
            const logMessageInput = findInput(inputs, 'log_message')
            expect(logMessageInput).toBeDefined()
            expect(logMessageInput.value).toBeDefined()
            expect(logMessageInput.scriptActive).toBe(false)
            expect(logMessageInput.parameter.type).toBe('string')

            // Verify log_message contains data pills referencing createCatalogTask outputs
            expect(logMessageInput.value).toContain('{{')
            expect(logMessageInput.value).toContain('}}')

            // Should reference the static output 'Catalog Task' (note: bracket notation in code becomes property access in data pill)
            // Should also reference __action_status__.message
            const value = logMessageInput.value
            expect(value).toMatch(/\{\{[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\./)

            // Verify displayValue matches value
            expect(logMessageInput.displayValue).toBe(logMessageInput.value)
        })
    })

    describe('Catalog Item Definition', () => {
        test('should reference catalog item in action inputs', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            // The catalog item should be referenced in the action inputs
            const flowRecord = merged['sys_hub_flow'][0]
            expect(flowRecord).toBeDefined()

            // Check that action instances reference the catalog item
            const actionInstance = merged['sys_hub_action_instance_v2'][0]
            const inputs = unzipInputArray(actionInstance.values)

            const templateInput = findInput(inputs, 'template_catalog_item')
            expect(templateInput).toBeDefined()
            expect(templateInput.value).toBeDefined()
            expect(typeof templateInput.value).toBe('string')

            // Verify parameter type is reference
            expect(templateInput.parameter).toBeDefined()
            expect(templateInput.parameter.type).toBe('reference')

            // Verify scriptActive is false
            expect(templateInput.scriptActive).toBe(false)

            // Verify value is a UUID (32 hex characters)
            expect(templateInput.value).toMatch(/^[a-f0-9]{32}$/)

            // Verify displayValue contains the catalog item name
            expect(templateInput.displayValue).toBeDefined()
            expect(typeof templateInput.displayValue).toBe('string')
        })

        test('should support various catalog variable types', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            const getCatalogVarsAction = merged['sys_hub_action_instance_v2'][0]
            const inputs = unzipInputArray(getCatalogVarsAction.values)
            const catalogVarsInput = findInput(inputs, 'catalog_variables')

            // Verify catalog variables input exists and has a value
            expect(catalogVarsInput).toBeDefined()
            expect(catalogVarsInput.value).toBeDefined()
            expect(typeof catalogVarsInput.value).toBe('string')
        })

        test('should handle requested_item input with data pill reference', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            const getCatalogVarsAction = merged['sys_hub_action_instance_v2'][0]
            const inputs = unzipInputArray(getCatalogVarsAction.values)

            const requestedItemInput = findInput(inputs, 'requested_item')
            expect(requestedItemInput).toBeDefined()

            // Verify parameter type is reference
            expect(requestedItemInput.parameter).toBeDefined()
            expect(requestedItemInput.parameter.type).toBe('reference')

            // Verify scriptActive is false
            expect(requestedItemInput.scriptActive).toBe(false)

            // Verify value contains data pill reference to trigger output
            expect(requestedItemInput.value).toBeDefined()
            expect(requestedItemInput.value).toContain('{{')
            expect(requestedItemInput.value).toContain('}}')
            expect(requestedItemInput.value).toContain('request_item')

            // Verify displayValue matches value for data pills
            expect(requestedItemInput.displayValue).toBe(requestedItemInput.value)
        })
    })

    describe('Service Catalog Trigger', () => {
        test('should use service catalog trigger with correct configuration', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            const triggerInstance = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type is service catalog
            expect(triggerInstance.trigger_type).toBe('service_catalog')

            // Verify run_flow_in configuration
            const inputs = unzipInputArray(triggerInstance.trigger_inputs)
            const runFlowInInput = findInput(inputs, 'run_flow_in')
            expect(runFlowInInput).toBeDefined()
            expect(runFlowInInput.value).toBe('background')
        })

        test('should have request_item output in trigger', async () => {
            const merged = await getMergedRecordUpdates(
                new Project({ rootDir: path.resolve(__dirname, 'project') }),
                'flow-catalog-get-variables.now.ts'
            )

            // Verify trigger instance exists
            const triggerInstance = merged['sys_hub_trigger_instance_v2'][0]
            expect(triggerInstance).toBeDefined()
            expect(triggerInstance.sys_id).toBeDefined()

            // Service catalog trigger should have request_item as an output
            // This is used by actions in the flow body
            expect(triggerInstance.trigger_type).toBe('service_catalog')
        })
    })
})
